   309→// Value - 런타임 값
   310→// ============================================================================
   311→
   312→#[derive(Debug, Clone)]
   313→enum Value {
   314→    Integer(i64),
   315→    Boolean(bool),
   316→    String(String),
   317→    Array(Vec<Value>),
   318→    Null,
   319→}
   320→
   321→impl Value {
   322→    fn to_string(&self) -> String {
   323→        match self {
   324→            Value::Integer(n) => n.to_string(),
   325→            Value::Boolean(b) => b.to_string(),
   326→            Value::String(s) => s.clone(),
   327→            Value::Array(_) => "[array]".to_string(),
   328→            Value::Null => "null".to_string(),
   329→        }
   330→    }
   331→}
