   333→// ============================================================================
   334→// VM - 가상 머신
   335→// ============================================================================
   336→
   337→struct VM {
   338→    variables: HashMap<String, Value>,
   339→    functions: HashMap<String, Vec<Token>>,
   340→}
   341→
   342→impl VM {
   343→    fn new() -> Self {
   344→        VM {
   345→            variables: HashMap::new(),
   346→            functions: HashMap::new(),
   347→        }
   348→    }
   349→
   350→    fn set_variable(&mut self, name: String, value: Value) {
   351→        self.variables.insert(name, value);
   352→    }
   353→
   354→    fn get_variable(&self, name: &str) -> Option<Value> {
   355→        self.variables.get(name).cloned()
   356→    }
   357→
   358→    fn eval_expression(&self, tokens: &[Token]) -> Value {
   359→        if tokens.is_empty() {
   360→            return Value::Null;
   361→        }
   362→
   363→        match &tokens[0] {
   364→            Token::Number(n) => Value::Integer(*n),
   365→            Token::String(s) => Value::String(s.clone()),
   366→            Token::True => Value::Boolean(true),
   367→            Token::False => Value::Boolean(false),
   368→            Token::Identifier(name) => self.get_variable(name).unwrap_or(Value::Null),
   369→            _ => Value::Null,
   370→        }
   371→    }
   372→}
