   524→        let mut input = String::new();
   525→        io::stdin().read_line(&mut input).unwrap();
   526→
   527→        let input = input.trim();
   528→        if input == "exit" {
   529→            println!("Goodbye!");
   530→            break;
   531→        }
   532→
   533→        let parts: Vec<&str> = input.split_whitespace().collect();
   534→        match parts.as_slice() {
   535→            ["set", var, value] => {
   536→                if let Ok(n) = value.parse::<i64>() {
   537→                    vm.set_variable(var.to_string(), Value::Integer(n));
   538→                    println!("Set {} = {}", var, n);
   539→                } else {
   540→                    vm.set_variable(var.to_string(), Value::String(value.to_string()));
   541→                    println!("Set {} = \"{}\"", var, value);
   542→                }
   543→            }
   544→            ["get", var] => {
   545→                if let Some(val) = vm.get_variable(var) {
   546→                    println!("{} = {}", var, val.to_string());
   547→                } else {
   548→                    println!("Variable {} not found", var);
   549→                }
   550→            }
   551→            ["test"] => {
   552→                let mut validator = Challenge14Validator::new();
